import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { nowIso, openDatabase, toJob, type JobRow } from './db.ts';
import { validateSubmission, type FieldError, type Submission } from './validation.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up only if its heartbeat is younger than this. */
const WORKER_FRESH_MS = 3000;
const MAX_BODY_BYTES = 64 * 1024;

const stmts = {
  allJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  idempotencyByKey: db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?'),
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
  ),
  insertIdempotency: db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)'),
  workerHeartbeat: db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'"),
};

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function workerUp(): boolean {
  const row = stmts.workerHeartbeat.get() as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at < WORKER_FRESH_MS;
}

function readBody(req: IncomingMessage): Promise<{ body: string; bodyTooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let bodyTooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) bodyTooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ body: Buffer.concat(chunks).toString('utf8'), bodyTooLarge }));
    req.on('error', reject);
  });
}

type SubmitResult = { kind: 'created' | 'replayed'; job: JobRow } | { kind: 'conflict' };

/**
 * Creates a job, or resolves an Idempotency-Key. The lookup and insert run in one immediate
 * transaction, so a key can never create two jobs, including across restarts.
 */
function submit(s: Submission, key: string | undefined): SubmitResult {
  const payload = JSON.stringify([s.input, s.steps, s.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const prior = stmts.idempotencyByKey.get(key) as { payload: string; job_id: string } | undefined;
      if (prior) {
        db.exec('COMMIT');
        if (prior.payload !== payload) return { kind: 'conflict' };
        return { kind: 'replayed', job: stmts.jobById.get(prior.job_id) as unknown as JobRow };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    stmts.insertJob.run(id, s.input, s.steps, s.failAttempts, now, now);
    if (key !== undefined) stmts.insertIdempotency.run(key, payload, id);
    db.exec('COMMIT');
    return { kind: 'created', job: stmts.jobById.get(id) as unknown as JobRow };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { body, bodyTooLarge } = await readBody(req);
  const v = validateSubmission({
    contentType: req.headers['content-type'],
    body,
    bodyTooLarge,
    idempotencyKey: req.headers['idempotency-key'],
  });
  if (!v.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', v.fields);
    return;
  }
  const result = submit(v.value, v.key);
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, result.kind === 'created' ? 201 : 200, toJob(result.job));
}

const ROUTES: Array<{ pattern: RegExp; methods: string[] }> = [
  { pattern: /^\/health$/, methods: ['GET'] },
  { pattern: /^\/$/, methods: ['GET'] },
  { pattern: /^\/api\/jobs$/, methods: ['GET', 'POST'] },
  { pattern: /^\/api\/jobs\/[^/]+$/, methods: ['GET'] },
];

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  const route = ROUTES.find((r) => r.pattern.test(pathname));
  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  if (!route.methods.includes(method)) {
    res.setHeader('Allow', route.methods.join(', '));
    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
    return;
  }

  if (pathname === '/health') {
    send(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
    return;
  }
  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return createJobRoute(req, res);
    const rows = stmts.allJobs.all() as unknown as JobRow[];
    send(res, 200, { jobs: rows.map(toJob) });
    return;
  }

  let id: string;
  try {
    id = decodeURIComponent(pathname.slice('/api/jobs/'.length));
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  const row = stmts.jobById.get(id) as unknown as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  send(res, 200, toJob(row));
}

const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

