import { setTimeout as sleep } from 'node:timers/promises';
import { nowIso, openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const stmts = {
  heartbeat: db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ),
  // Only one worker runs at a time, so any job still 'running' was left behind by a dead worker.
  // The interrupted attempt is un-counted so it is resumed under the same attempt number. Its
  // retry rule then applies exactly as if it had not been interrupted.
  requeueInterrupted: db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, attempts = attempts - 1, updated_at = ? WHERE status = 'running'",
  ),
  nextQueued: db.prepare(
    "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
  ),
  startAttempt: db.prepare(
    "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
  ),
  progress: db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?'),
  complete: db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, output_json = ?, updated_at = ? WHERE id = ?",
  ),
  // A failed attempt keeps its count: the next attempt is attempts + 1.
  requeue: db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ?",
  ),
  // An interrupted attempt (clean shutdown) is un-counted, so the next claim resumes the same number.
  abandon: db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, attempts = attempts - 1, available_at = ?, updated_at = ? WHERE id = ?",
  ),
  fail: db.prepare(
    "UPDATE jobs SET status = 'failed', completed = 0, error = 'transient failure', updated_at = ? WHERE id = ?",
  ),
};

function beat(): void {
  stmts.heartbeat.run(Date.now());
}

/** Runs one processing attempt. The attempt counter was already incremented by the caller. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt > MAX_ATTEMPTS) {
    // Defensive: no attempt beyond the limit may run. Such a job is terminal.
    stmts.fail.run(nowIso(), job.id);
    return;
  }

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) stmts.fail.run(nowIso(), job.id);
    else stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Clean shutdown: hand the job back so it is not stuck in 'running'.
      stmts.requeue.run(0, nowIso(), job.id);
      return;
    }
    stmts.progress.run(step, nowIso(), job.id);
  }
  const input = JSON.parse(job.input_json) as string;
  stmts.complete.run(JSON.stringify(input.toUpperCase()), nowIso(), job.id);
}

const recovered = stmts.requeueInterrupted.run(nowIso()).changes;
if (recovered) console.log(`re-queued ${recovered} interrupted job(s)`);
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  const job = stmts.nextQueued.get(Date.now()) as unknown as JobRow | undefined;
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  const attempt = job.attempts + 1;
  stmts.startAttempt.run(nowIso(), job.id);
  await runAttempt(job, attempt);
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');
